import { HostedChildStreamIdleTimeoutError } from "./child-stream-watchdog.js";
/** Entry shape for write hosted child execution log. */
export function writeHostedChildExecutionLogEntry(entry, writer) {
    if (entry.level === "error") {
        writer.error(entry.message, entry.context);
        return;
    }
    if (entry.level === "info") {
        writer.info(entry.message, entry.context);
        return;
    }
    writer.warn(entry.message, entry.context);
}
/** Create hosted child execution log writer. */
export function createHostedChildExecutionLogWriter(writer) {
    return (entry) => {
        writeHostedChildExecutionLogEntry(entry, writer);
    };
}
/** Builds hosted child exhausted step budget log. */
export function buildHostedChildExhaustedStepBudgetLog(input) {
    return {
        level: "warn",
        message: "Child fork exhausted step budget",
        context: {
            description: input.description,
            kind: input.kind,
            stepCount: input.stepCount,
            maxSteps: input.maxSteps,
            toolCalls: input.toolCallsLength,
        },
    };
}
/** Builds the log entry for a child run that produced no text and no tool results. */
export function buildHostedChildEmptyResultLog(input) {
    return {
        level: "warn",
        message: "Child fork completed without a result",
        context: {
            description: input.description,
            kind: input.kind,
            stepCount: input.stepCount,
            toolCalls: input.toolCallsLength,
        },
    };
}
/** Builds hosted child completed log. */
export function buildHostedChildCompletedLog(input) {
    return {
        level: "info",
        message: "Child fork completed",
        context: {
            description: input.description,
            kind: input.kind,
            toolCalls: input.toolCallsLength,
            resultLength: input.finalText.length,
            resultPreview: input.finalText.substring(0, 200),
        },
    };
}
/** Builds hosted child error log. */
export function buildHostedChildErrorLog(input) {
    if (input.error instanceof HostedChildStreamIdleTimeoutError) {
        return {
            level: "warn",
            message: "Child fork stream stalled",
            context: {
                description: input.description,
                kind: input.kind,
                phase: input.error.phase,
                idleTimeoutMs: input.error.timeoutMs,
                partialTextLength: input.finalText.length,
                toolCalls: input.toolCallsLength,
                toolResults: input.toolResultsLength,
            },
        };
    }
    return {
        level: "error",
        message: "Child fork failed",
        context: {
            description: input.description,
            kind: input.kind,
            error: input.error,
        },
    };
}
